import{_ as a,o as i,c as n,a6 as e}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"DNS 加固：DNSSEC 与 CAA","description":"DNS 明文、无认证，天生可被投毒——DNSSEC 用签名链解决「这条应答是真的吗」，CAA 用一行记录限定谁能给你签证书。附完整验证命令与常见配错。","frontmatter":{"title":"DNS 加固：DNSSEC 与 CAA","description":"DNS 明文、无认证，天生可被投毒——DNSSEC 用签名链解决「这条应答是真的吗」，CAA 用一行记录限定谁能给你签证书。附完整验证命令与常见配错。","source":"https://daiw.org/manual/web-security/dns-hardening"},"headers":[],"relativePath":"manual/computer-programming/web-security/dns-hardening.md","filePath":"manual/computer-programming/web-security/dns-hardening.md"}'),t={name:"manual/computer-programming/web-security/dns-hardening.md"};function p(l,s,r,h,d,o){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="dns-加固-dnssec-与-caa" tabindex="-1">DNS 加固：DNSSEC 与 CAA <a class="header-anchor" href="#dns-加固-dnssec-与-caa" aria-label="Permalink to &quot;DNS 加固：DNSSEC 与 CAA&quot;">​</a></h1><p>DNS 明文、无认证，天生可被投毒——DNSSEC 用签名链解决「这条应答是真的吗」，CAA 用一行记录限定谁能给你签证书。附完整验证命令与常见配错。</p><p>DNS 是互联网最老的协议之一，设计时<strong>没考虑任何安全</strong>：明文传输、无来源认证、谁抢先应答谁赢。这一章讲两个能直接配上的加固项。</p><h2 id="问题-dns-应答是可以伪造的" tabindex="-1">问题：DNS 应答是可以伪造的 <a class="header-anchor" href="#问题-dns-应答是可以伪造的" aria-label="Permalink to &quot;问题：DNS 应答是可以伪造的&quot;">​</a></h2><p>递归解析器问权威服务器「example.com 的 A 记录是什么」，权威回一个 UDP 包。<strong>任何能抢在真应答之前伪造一个包的人，都能让解析器缓存一个假 IP</strong>——这就是缓存投毒。</p><p>投毒成功后，用户输入正确的域名，连到攻击者的服务器，<strong>浏览器地址栏完全正常</strong>。唯一的破绽是 HTTPS：攻击者没有你的证书。所以现实中的投毒往往配合降级或钓鱼页使用。</p><h2 id="dnssec-给应答签名" tabindex="-1">DNSSEC：给应答签名 <a class="header-anchor" href="#dnssec-给应答签名" aria-label="Permalink to &quot;DNSSEC：给应答签名&quot;">​</a></h2><p>DNSSEC 给每条记录加数字签名，形成一条从根域到你的域的<strong>信任链</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根（.） → 顶级域（.com） → 你的域（example.com）</span></span>
<span class="line"><span>每一层用自己的密钥签下一层的密钥指纹（DS 记录）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>解析器逐级验签，任何一环对不上就拒绝这个应答。</p><p><strong>开启方式</strong>（各家控制台位置不同，逻辑一致）：</p><ol><li>在 DNS 托管商处启用 DNSSEC，它会生成 DNSKEY 并给你一段 <strong>DS 记录</strong>。</li><li>把这段 DS 记录填到<strong>注册商</strong>那边（注意：是注册商，不是 DNS 托管商）。</li><li>等待 TTL 生效。</li></ol><p><strong>验证</strong>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看 DS 记录是否已在父域发布</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 完整验签（ad 标志出现表示 Authenticated Data，验签通过）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +dnssec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +multi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> A</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;flags:|RRSIG&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>看到 <code>flags: qr rd ra ad</code> 里的 <strong><code>ad</code></strong>，说明验签成功。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>DNSSEC 配错会让域名整个解析失败，比不配更危险。</strong> 最典型的翻车：<strong>换 DNS 服务商时忘了同步更新 DS 记录</strong>——新服务商的密钥和注册商那边登记的 DS 对不上，所有开启验证的解析器会直接拒绝解析，你的域名对一部分用户彻底消失。</p><p>换 DNS 服务商的正确顺序：先在注册商处<strong>移除 DS 记录</strong>、等旧 TTL 过期、再切服务商、最后重新发布新的 DS。别图省事一步到位。</p></div><p><strong>要清楚 DNSSEC 不解决什么</strong>：</p><ul><li>不加密（DNS 查询内容仍然明文可见，那是 DoH/DoT 的事）。</li><li>不防止「攻击者登录你的后台改了记录」——那种改动是<strong>合法签名</strong>的。</li><li>覆盖率有限：不是所有递归解析器都验签。</li></ul><h2 id="caa-限定谁能给你签证书" tabindex="-1">CAA：限定谁能给你签证书 <a class="header-anchor" href="#caa-限定谁能给你签证书" aria-label="Permalink to &quot;CAA：限定谁能给你签证书&quot;">​</a></h2><p>这是一条<strong>性价比极高</strong>的记录，一行就能挡掉一整类攻击。</p><p><strong>背景</strong>：公共 CA 有几百家，理论上<strong>任何一家</strong>都能给 <code>example.com</code> 签发证书。历史上多次发生 CA 被攻破或误签，攻击者拿到一张合法证书，就能做中间人而浏览器不报警。</p><p>CAA 记录告诉所有 CA：<strong>只有我列出的这几家可以给我签</strong>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com.  IN  CAA  0 issue &quot;letsencrypt.org&quot;</span></span>
<span class="line"><span>example.com.  IN  CAA  0 issue &quot;digicert.com&quot;</span></span>
<span class="line"><span>example.com.  IN  CAA  0 issuewild &quot;;&quot;</span></span>
<span class="line"><span>example.com.  IN  CAA  0 iodef &quot;mailto:security@example.com&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>逐行解释：</p><table tabindex="0"><thead><tr><th>行</th><th>含义</th></tr></thead><tbody><tr><td><code>issue &quot;letsencrypt.org&quot;</code></td><td>允许 Let&#39;s Encrypt 签发普通证书</td></tr><tr><td><code>issue &quot;digicert.com&quot;</code></td><td>也允许 DigiCert（多写几家备用，避免换 CA 时被自己卡住）</td></tr><tr><td><code>issuewild &quot;;&quot;</code></td><td><strong>禁止任何人签发泛域名证书</strong>（<code>;</code> 表示禁止）。如果你不用泛域名，这一行务必加上</td></tr><tr><td><code>iodef &quot;mailto:...&quot;</code></td><td>有 CA 收到不合规申请时，往这个地址报告</td></tr></tbody></table><p><strong>验证</strong>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CAA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>申请证书前先自查</strong>，避免配了 CAA 反而把自己的续期卡死：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 确认你正在用的 CA 在允许列表里</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CAA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的CA域名&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>CAA 是继承的。</strong> 查 <code>blog.example.com</code> 时，如果它自己没有 CAA 记录，CA 会向上查 <code>example.com</code>。所以在<strong>根域</strong>配一次，通常就覆盖了全部子域——这也意味着，如果某个子域需要用别的 CA，得单独给它配一条更宽松的记录。</p></div><h2 id="其它几条值得顺手做的" tabindex="-1">其它几条值得顺手做的 <a class="header-anchor" href="#其它几条值得顺手做的" aria-label="Permalink to &quot;其它几条值得顺手做的&quot;">​</a></h2><p><strong>一、关掉区域传送（AXFR）。</strong> 配错的权威服务器会把整个区域文件给任何人，等于把你的内网结构、测试环境域名全交出去：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 自查:应该返回 &quot;Transfer failed&quot; 之类的拒绝</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AXFR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @你的权威服务器</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>二、SPF / DKIM / DMARC。</strong> 即使你不发邮件，也要配——<strong>防止别人冒用你的域名发钓鱼邮件</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>; 明确声明「本域名不发邮件」</span></span>
<span class="line"><span>example.com.       IN  TXT  &quot;v=spf1 -all&quot;</span></span>
<span class="line"><span>_dmarc.example.com. IN TXT  &quot;v=DMARC1; p=reject; rua=mailto:dmarc@example.com&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这两行对纯网站域名尤其重要。不配的话，任何人都能伪造 <code>noreply@example.com</code> 发钓鱼信，收信方无从判断真伪，最后砸的是你的品牌。</p><p><strong>三、TTL 别设太长。</strong> 应急切换时，TTL 就是你的最小恢复时间。核心记录建议 300~600 秒；准备做变更前提前调低。</p><p><strong>四、清理僵尸记录。</strong> 指向已下线服务的 CNAME 是子域名接管的温床——<a href="/Front2Full/manual/computer-programming/web-security/subdomain-takeover">下一章</a>专讲这个。</p><h2 id="一次性自查" tabindex="-1">一次性自查 <a class="header-anchor" href="#一次性自查" aria-label="Permalink to &quot;一次性自查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.com</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;── NS ──&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;        </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    $D</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;── DS ──&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;        </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    $D</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;── CAA ──&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;       </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CAA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   $D</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;── SPF ──&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;       </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TXT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   $D </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spf</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;── DMARC ──&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;     </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TXT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _dmarc.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$D</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;── DNSSEC ad ──&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +dnssec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $D </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">A</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;flags:[^;]*&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DNS 天生无认证，<strong>DNSSEC 用签名链解决来源可信</strong>，但不加密、也管不住「后台被登录后的合法改动」。</li><li><strong>换 DNS 服务商时 DS 记录不同步，会让域名整体解析失败</strong>——比不开 DNSSEC 更危险，务必按顺序操作。</li><li><strong>CAA 一行记录挡掉「任意 CA 误签」这一整类风险</strong>，不用泛域名的话记得 <code>issuewild &quot;;&quot;</code>。</li><li>不发邮件的域名也要配 SPF/DMARC，否则会被拿去发钓鱼。</li></ul><p>下一章讲一个几乎每个稍大点的组织都中过招的洞。👉 <a href="/Front2Full/manual/computer-programming/web-security/subdomain-takeover">子域名接管</a></p>`,43)])])}const g=a(t,[["render",p]]);export{c as __pageData,g as default};
